pub fn factorial_of_last_digit(n: u64) -> u64 {
    // Since the last decimal digit of n is between 0 and 9,
    // we can precompute all factorials from 0! to 9!.
    const FACTORIALS: [u64; 10] = [
        1,       // 0!
        1,       // 1!
        2,       // 2!
        6,       // 3!
        24,      // 4!
        120,     // 5!
        720,     // 6!
        5040,    // 7!
        40320,   // 8!
        362880,  // 9!
    ];

    let last_digit = (n % 10) as usize;
    FACTORIALS[last_digit]
}

